css:
/* --mq-* берите из токенов дизайн-системы: background, surface, text, text_muted, border, link */
.mq{--mq-bg:#FFFFFF;--mq-surface:#F4F4F2;--mq-text:#1A1A1A;--mq-muted:#5C5C5C;--mq-border:#DEDED9;--mq-focus:#1A56DB;--mq-gap:56px;--mq-fade:clamp(24px,6vw,72px);padding-block:64px;background:var(--mq-bg);color:var(--mq-text)}
.mq__head{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:16px;max-width:1200px;margin:0 auto 32px;padding-inline:16px}
.mq__title{flex:1 1 12em;margin:0;font-size:clamp(20px,2.4vw,28px);line-height:1.2}
.mq__toggle{flex:none;display:inline-flex;white-space:nowrap;align-items:center;gap:10px;min-height:44px;padding:10px 18px;border:1px solid var(--mq-border);border-radius:999px;background:transparent;color:var(--mq-text);font:inherit;font-size:14px;cursor:pointer;position:relative;isolation:isolate}
.mq__toggle[hidden]{display:none}
.mq__toggle::before{content:"";flex:none;width:10px;height:12px;box-sizing:border-box;border-inline:3px solid currentColor}
.mq[data-paused] .mq__toggle::before{border:0;background:currentColor;clip-path:polygon(0 0,100% 50%,0 100%)}
.mq__toggle::after{content:"";position:absolute;inset:0;z-index:-1;border-radius:inherit;background:var(--mq-surface);opacity:0;transition:opacity 150ms cubic-bezier(.2,0,0,1)}
.mq__toggle:hover::after{opacity:1}
.mq__toggle:focus-visible{outline:2px solid var(--mq-focus);outline-offset:2px}
.mq__viewport+.mq__viewport{margin-top:24px}
.mq__viewport.mq--cards{--mq-gap:20px}
.mq--cards .mq__group{align-items:stretch}
.mq__track{display:flex}
.mq__group{display:flex;flex:1 1 auto;flex-wrap:wrap;justify-content:center;align-items:center;gap:24px var(--mq-gap);margin:0;padding:0 16px;list-style:none}
.mq__item{flex:none}
.mq__logo{display:block;height:40px;width:auto;opacity:.7;filter:grayscale(1);transition:opacity 240ms cubic-bezier(.2,0,0,1),filter 240ms cubic-bezier(.2,0,0,1)}
.mq__item:hover .mq__logo{opacity:1;filter:none}
.mq__word{font-size:20px;font-weight:700;letter-spacing:-.01em;color:var(--mq-muted);white-space:nowrap}
.mq__card{flex:none;display:flex;flex-direction:column;gap:16px;box-sizing:border-box;width:min(360px,80vw);padding:24px;border:1px solid var(--mq-border);border-radius:16px;background:var(--mq-surface)}
.mq__quote{margin:0;font-size:16px;line-height:1.5}
.mq__who{margin:auto 0 0;font-size:14px;color:var(--mq-muted)}
.mq__who a{color:inherit}
@keyframes mq-scroll{from{transform:translate3d(0,0,0)}to{transform:translate3d(-50%,0,0)}}
/* Движение включается только тем, кто не просил его убрать. Раскладка в одну строку и место под кнопку — сразу, до JS: сдвига макета нет */
@media (prefers-reduced-motion:no-preference){
  .mq__toggle[hidden]{display:inline-flex;visibility:hidden} /* кнопка невидима и недоступна до запуска, но место за ней уже занято */
  .mq__viewport{overflow:hidden;padding-block:4px;-webkit-mask-image:linear-gradient(90deg,transparent,#000 var(--mq-fade),#000 calc(100% - var(--mq-fade)),transparent);mask-image:linear-gradient(90deg,transparent,#000 var(--mq-fade),#000 calc(100% - var(--mq-fade)),transparent)}
  .mq__track{width:max-content}
  .mq__group{flex:none;flex-wrap:nowrap;justify-content:flex-start;padding:0 var(--mq-gap) 0 0}
  .mq.is-ready .mq__track{animation:mq-scroll var(--mq-duration,40s) linear infinite;will-change:transform}
  .mq.is-ready .mq--reverse .mq__track{animation-direction:reverse}
  .mq.is-ready[data-paused] .mq__track,.mq.is-ready[data-offscreen] .mq__track{animation-play-state:paused}
  .mq.is-ready .mq__viewport:focus-within .mq__track{animation:none} /* фокус с клавиатуры: лента встаёт в начало, фокус всегда виден */
  .mq.is-ready .mq__viewport:focus-within{-webkit-mask-image:none;mask-image:none} /* затухание краёв не прячет сфокусированный элемент */
}
@media (prefers-reduced-motion:no-preference) and (hover:hover){
  .mq.is-ready .mq__viewport:hover .mq__track{animation-play-state:paused}
}
/* Уровень 1 по схеме iart: бесконечная лента убирается целиком, всё содержимое видно статичной сеткой */
@media (prefers-reduced-motion:reduce){
  .mq__track{animation:none!important;transform:none!important}
  .mq__group[data-clone],.mq__toggle{display:none!important}
  .mq__logo,.mq__toggle::after{transition:none}
}

js:
(() => {
  const motionOk = matchMedia('(prefers-reduced-motion: no-preference)');
  document.querySelectorAll('.mq').forEach((root) => {
    const btn = root.querySelector('.mq__toggle'), lanes = [...root.querySelectorAll('.mq__viewport')], seen = new Map();
    const build = () => root.classList.contains('is-ready') && lanes.forEach((vp) => {
      const track = vp.querySelector('.mq__track'), group = track.querySelector('.mq__group');
      const w = group.getBoundingClientRect().width, vw = vp.clientWidth;
      if (!w || seen.get(vp) === w + ':' + vw) return;
      seen.set(vp, w + ':' + vw);
      track.querySelectorAll('[data-clone]').forEach((n) => n.remove());
      const k = Math.max(1, Math.ceil(vw / w)); // половина ленты не уже экрана, иначе виден разрыв
      for (let i = 1; i < k * 2; i++) {
        const c = group.cloneNode(true);
        c.setAttribute('data-clone', ''); c.setAttribute('aria-hidden', 'true'); c.inert = true;
        c.querySelectorAll('a,button,input,select,textarea,[tabindex]').forEach((el) => { el.tabIndex = -1; });
        track.append(c);
      }
      const speed = Number(vp.dataset.speed || root.dataset.speed) || 40; // пикселей в секунду
      track.style.setProperty('--mq-duration', ((w * k) / speed).toFixed(2) + 's');
    });
    const ro = new ResizeObserver(() => requestAnimationFrame(build));
    const io = new IntersectionObserver((es) => root.toggleAttribute('data-offscreen', !es[es.length - 1].isIntersecting));
    const start = () => {
      root.classList.add('is-ready'); if (btn) btn.hidden = false;
      lanes.forEach((vp) => { ro.observe(vp); ro.observe(vp.querySelector('.mq__group')); });
      io.observe(root); build();
    };
    const stop = () => {
      ro.disconnect(); io.disconnect(); seen.clear(); root.classList.remove('is-ready'); root.removeAttribute('data-offscreen');
      if (btn) btn.hidden = true;
      root.querySelectorAll('[data-clone]').forEach((n) => n.remove());
    };
    btn?.addEventListener('click', () => {
      btn.textContent = root.toggleAttribute('data-paused') ? 'Запустить ленту' : 'Остановить ленту';
    });
    lanes.forEach((vp) => vp.addEventListener('focusout', () => { vp.scrollLeft = 0; }));
    const sync = () => (motionOk.matches ? start() : stop());
    motionOk.addEventListener('change', sync); sync();
  });
})();
